      "path": "packages/dsh-ssh/src/engine.ts",
      "content": "/**\n * The SSH engine facade: a per-alias persistent connection pool (ssh2) with\n * multi-hop jump support, command execution, PTY shells, SFTP transfers,\n * local port-forward tunnels and cluster execution. The heavy lifting lives\n * in the engine/ modules (connection-pool, pty, sftp, tunnel, cluster); this\n * class composes them behind one new SshEngine instance per plugin apply.\n */\n\nimport type { ClusterResult, ExecResult, SshHostSummary, TestResult, TransferProgress, TunnelInfo } from './protocol.ts'\nimport type { HostStore } from './store.ts'\nimport {\n  DEFAULTS,\n  execCommand,\n  disposeRecord,\n  sweepPool,\n  type EngineOptions,\n  type KeyboardInteractiveHandler,\n  type PoolRecord,\n} from './engine/connection-pool.ts'\nimport { openShell, type ShellSession } from './engine/pty.ts'\nimport { download, ls, upload } from './engine/sftp.ts'\nimport { listTunnels, startTunnel, stopAllTunnels, stopTunnel, type TunnelRecord } from './engine/tunnel.ts'\nimport { cluster } from './engine/cluster.ts'\n\nexport type { EngineOptions, KeyboardInteractiveHandler } from './engine/connection-pool.ts'\nexport type { ShellSession } from './engine/pty.ts'\nexport type { PoolRecord } from './engine/connection-pool.ts'\nexport type { TunnelRecord } from './engine/tunnel.ts'\n\n/**\n * The engine. Owns the pool, tunnels, and all operations. One instance per\n * plugin apply; dispose() closes every connection.\n */\nexport class SshEngine {\n  readonly store: HostStore\n  readonly opts: Required<EngineOptions>\n  readonly pool = new Map<string, PoolRecord>()\n  readonly acquireQueue = new Map<string, Promise<PoolRecord>>()\n  readonly tunnels = new Map<string, TunnelRecord>()\n  nextTunnelId = 1\n  private sweepTimer: NodeJS.Timeout | undefined\n\n  /**\n   * @param store - the host config store.\n   * @param options - engine knobs (defaults applied).\n   */\n  constructor(store: HostStore, options?: EngineOptions) {\n    this.store = store\n    this.opts = { ...DEFAULTS, ...options }\n    this.sweepTimer = setInterval(() => sweepPool(this), Math.max(10_000, this.opts.idleTimeoutMs / 4))\n    this.sweepTimer.unref?.()\n  }\n\n  /**\n   * Change the pre-ready ceiling (TCP connect + key exchange + user\n   * authentication) for connections opened from now on. A pooled connection\n   * keeps serving until it reconnects, because the ceiling governs the\n   * connect path only.\n   */\n  setConnectTimeout(timeoutMs: number): void {\n    this.opts.connectTimeoutMs = timeoutMs\n  }\n\n  // ---------------------------------------------------------------- config\n\n  /** Secret-free host list (filtered by the optional query). */\n  list(query?: string): SshHostSummary[] {\n    const needle = query?.trim().toLowerCase()\n    return this.store.list()\n      .filter(entry => needle === undefined || needle === ''\n        || entry.alias.toLowerCase().includes(needle)\n        || (entry.description ?? '').toLowerCase().includes(needle)\n        || entry.host.toLowerCase().includes(needle)\n        || entry.tags.some(tag => tag.toLowerCase().includes(needle)))\n      .map(entry => this.store.summarize(entry))\n  }\n\n  /** One host summary by alias. */\n  find(alias: string): SshHostSummary | undefined {\n    const entry = this.store.find(alias)\n    return entry === undefined ? undefined : this.store.summarize(entry)\n  }\n\n  // ------------------------------------------------------------ exec\n\n  /** Run one command on `alias` (reusing the pooled connection). */\n  async exec(alias: string, command: string, timeoutMs?: number, signal?: AbortSignal): Promise<ExecResult> {\n    return execCommand(this, alias, command, timeoutMs, signal)\n  }\n\n  /** Run one command against many hosts concurrently. */\n  async cluster(options: {\n    command: string\n    aliases?: string[]\n    environment?: string\n    tags?: string[]\n    timeoutMs?: number\n    maxWorkers?: number\n    signal?: AbortSignal\n  }): Promise<ClusterResult[]> {\n    return cluster(this, options)\n  }\n\n  // -------------------------------------------------------------- shell\n\n  /** Open a PTY shell session for the web terminal (standalone connection). */\n  async openShell(\n    alias: string,\n    size: { cols: number; rows: number },\n    onKeyboardInteractive?: KeyboardInteractiveHandler,\n  ): Promise<ShellSession> {\n    return openShell(this, alias, size, onKeyboardInteractive)\n  }\n\n  // -------------------------------------------------------------- sftp\n\n  /** Upload one local file (or directory tree) to a remote path. */\n  async upload(alias: string, localPath: string, remotePath: string, recursive: boolean, onProgress?: (progress: TransferProgress) => void): Promise<{ bytes: number; files: number }> {\n    return upload(this, alias, localPath, remotePath, recursive, onProgress)\n  }\n\n  /** Download one remote file to a local path. */\n  async download(alias: string, remotePath: string, localPath: string, onProgress?: (progress: TransferProgress) => void): Promise<{ bytes: number }> {\n    return download(this, alias, remotePath, localPath, onProgress)\n  }\n\n  /** List a remote directory (file browser). */\n  async ls(alias: string, path: string): Promise<import('./protocol.ts').RemoteDirEntry[]> {\n    return ls(this, alias, path)\n  }\n\n  // ------------------------------------------------------------- tunnel\n\n  /** Start a local port-forward tunnel (listens on 127.0.0.1 only). */\n  async startTunnel(alias: string, options: { remotePort: number; remoteHost?: string; localPort?: number }): Promise<TunnelInfo> {\n    return startTunnel(this, alias, options)\n  }\n\n  /** All active tunnels. */\n  listTunnels(): TunnelInfo[] {\n    return listTunnels(this)\n  }\n\n  /** Stop one tunnel (closes the listener, live sockets, and the pinned connection). */\n  stopTunnel(id: string): boolean {\n    return stopTunnel(this, id)\n  }\n\n  /** Stop all tunnels (optionally for one alias). */\n  stopAllTunnels(alias?: string): number {\n    return stopAllTunnels(this, alias)\n  }\n\n  /**\n   * Drop every live artifact bound to one alias: stop its tunnels and close\n   * the pooled connection. Host entries that are deleted or whose connection\n   * fields change must never keep serving a stale, previously authenticated\n   * connection — the next operation re-connects from the current config.\n   */\n  dropAlias(alias: string): void {\n    stopAllTunnels(this, alias)\n    disposeRecord(this, alias)\n  }\n\n  // ------------------------------------------------------------- misc\n\n  /** Probe connectivity with a cross-platform shell command. */\n  async test(alias: string): Promise<TestResult> {\n    const started = Date.now()\n    try {\n      const result = await this.exec(alias, 'echo ok', 10_000)\n      return result.success\n        ? { ok: true, latencyMs: result.durationMs }\n        : { ok: false, latencyMs: result.durationMs, error: 'remote exit code ' + result.exitCode }\n    } catch (error) {\n      return { ok: false, latencyMs: Date.now() - started, error: error instanceof Error ? error.message : String(error) }\n    }\n  }\n\n  /** Close every pooled connection and tunnel. */\n  dispose(): void {\n    if (this.sweepTimer !== undefined) clearInterval(this.sweepTimer)\n    for (const id of [...this.tunnels.keys()]) stopTunnel(this, id)\n    for (const alias of [...this.pool.keys()]) disposeRecord(this, alias)\n  }\n}\n"
    },
    {
      "path": "packages/dsh-ssh/src/tools.ts",
      "content": "/**\n * Agent tools: the DSH-native counterpart of ssh-skill's CLI. Every tool\n * talks to the same engine the web UI uses, so a host configured in the GUI\n * is immediately operable by any agent, and vice versa.\n */\n\nimport { defineTool } from '@deepseek-ai/dsh-tools'\nimport type { ContentBlock } from '@deepseek-ai/dsh-llm'\nimport type { SshEngine } from './engine.ts'\nimport type { ClusterResult, ExecResult, SshAuthKind, SshHostSummary, TunnelInfo } from './protocol.ts'\n\n/** One text content block (the only render shape these tools emit). */\nfunction text(value: string): ContentBlock[] {\n  return [{ type: 'text', text: value }]\n}\n\n/**\n * One host row for the agent surface. The ProxyCommand STRING is deliberately\n * projected to a boolean: the command may embed credentials for a bastion\n * client, and the model only needs to know that the host goes through one.\n */\nexport interface AgentHostRow {\n  alias: string\n  host: string\n  port: number\n  user: string\n  auth: SshAuthKind\n  keyReady: boolean\n  proxyJump: string[]\n  proxyCommandConfigured: boolean\n  forwardAgent: boolean\n  description?: string\n  environment?: string\n  tags: string[]\n  location?: string\n  createdAt: number\n  updatedAt: number\n}\n\n/** Project one summary onto the agent-facing row shape. */\nexport function toAgentHostRow(host: SshHostSummary): AgentHostRow {\n  const { proxyCommand, ...rest } = host\n  return { ...rest, proxyCommandConfigured: proxyCommand !== undefined }\n}\n\n/** Host table render shared by list surfaces. */\nfunction renderHosts(hosts: AgentHostRow[]): string {\n  if (hosts.length === 0) return 'no hosts configured'\n  const rows = hosts.map(host => [\n    host.alias,\n    host.host,\n    String(host.port),\n    host.user,\n    host.auth,\n    host.proxyJump.length > 0 ? 'jump:' + host.proxyJump.join(',') : host.proxyCommandConfigured ? 'proxy-command' : '-',\n    // Forwarding is a security-relevant opt-in (the remote can sign with this\n    // machine's agent), so the model must see it in the table, not only in JSON.\n    host.forwardAgent ? 'yes' : '-',\n    host.environment ?? '-',\n    (host.tags.length > 0 ? host.tags.join(',') : '-'),\n    host.description ?? '',\n  ].join(' | '))\n  return ['alias | host | port | user | auth | proxy | forward | environment | tags | description', '--- | --- | --- | --- | --- | --- | --- | --- | --- | ---', ...rows].join('\\n')\n}\n\n/** Render one exec result (mirrors the bash-tool exit-code convention). */\nfunction renderExec(result: ExecResult): string {\n  const marker = result.timedOut\n    ? '[timed out]'\n    : `[exit code: ${result.exitCode ?? 'null'}]`\n  const parts = [marker]\n  if (result.stdout !== '') parts.push('stdout:\\n' + result.stdout)\n  if (result.stderr !== '') parts.push('stderr:\\n' + result.stderr)\n  if (result.error !== undefined) parts.push('error: ' + result.error)\n  parts.push(`duration: ${result.durationMs} ms`)\n  return parts.join('\\n')\n}\n\n/** Render cluster outcomes compactly. */\nfunction renderCluster(results: ClusterResult[]): string {\n  if (results.length === 0) return 'no hosts matched'\n  return results.map(result => {\n    const status = result.ok ? 'ok' : result.timedOut === true ? 'timed out' : 'failed'\n    const tail = result.error !== undefined ? ' (' + result.error + ')' : ''\n    return `${result.alias}: ${status} [exit code: ${result.exitCode ?? 'null'}]${tail}`\n  }).join('\\n')\n}\n\n/** One tunnel line. */\nfunction renderTunnel(tunnel: TunnelInfo): string {\n  return `${tunnel.id} ${tunnel.alias} 127.0.0.1:${tunnel.localPort} -> ${tunnel.remoteHost}:${tunnel.remotePort} [${tunnel.state}]`\n}\n\n/** The host-list tool. */\nexport function sshListTool(engine: SshEngine) {\n  return defineTool({\n    name: 'ssh_list',\n    description: 'List configured SSH hosts (alias, host, user, auth, agent forwarding, environment, tags, description). Use ssh_exec etc. with the alias.',\n    parameters: {\n      query: { type: 'string', description: 'Optional fuzzy match against alias, description, host, and tags.' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          hosts: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                alias: { type: 'string', required: true },\n                host: { type: 'string', required: true },\n                port: { type: 'integer', required: true },\n                user: { type: 'string', required: true },\n                auth: { type: 'string', enum: ['key', 'password', 'agent'], required: true },\n                keyReady: { type: 'boolean', required: true },\n                proxyJump: { type: 'array', items: { type: 'string' }, required: true },\n                proxyCommandConfigured: { type: 'boolean', required: true },\n                forwardAgent: { type: 'boolean', required: true },\n                description: { type: 'string' },\n                environment: { type: 'string' },\n                tags: { type: 'array', items: { type: 'string' }, required: true },\n                location: { type: 'string' },\n                createdAt: { type: 'integer', required: true },\n                updatedAt: { type: 'integer', required: true },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value: { hosts?: AgentHostRow[] }) => text(renderHosts(value.hosts ?? [])),\n    },\n    // Reads the local host registry only: safe to overlap with sibling calls.\n    isConcurrencySafe: () => true,\n    async execute(args) {\n      return { hosts: engine.list(args.query).map(toAgentHostRow) }\n    },\n  })\n}\n\n/** The command-execution tool. */\nexport function sshExecTool(engine: SshEngine) {\n  return defineTool({\n    name: 'ssh_exec',\n    description: 'Execute a shell command on a REMOTE SSH host by alias; the command runs on the remote host, never on this machine. For commands on this machine, use the local bash tool. Prefer combining independent read-only queries into one command.',\n    parameters: {\n      alias: { type: 'string', required: true, description: 'Host alias from ssh_list.' },\n      command: { type: 'string', required: true, description: 'The shell command to run remotely.' },\n      timeoutMs: { type: 'integer', description: 'Remote command execution timeout in milliseconds (default 60000); it starts after the connection is ready. The connection and authentication ceiling is the dsh-ssh connectTimeoutMs setting, not this argument.' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          success: { type: 'boolean', required: true },\n          exitCode: { oneOf: [{ type: 'integer' }, { type: 'null' }], required: true },\n          timedOut: { type: 'boolean', required: true },\n          stdout: { type: 'string', required: true },\n          stderr: { type: 'string', required: true },\n          durationMs: { type: 'integer', required: true },\n          error: { type: 'string' },\n        },\n      },\n      render: (_args, value: ExecResult) => text(renderExec(value)),\n    },\n    async execute(args, exec) {\n      try {\n        // Forward the caller's cancellation: aborting closes the remote channel\n        // instead of leaving the command running on the host.\n        return await engine.exec(args.alias, args.command, args.timeoutMs, exec.signal)\n      } catch (error) {\n        return {\n          success: false,\n          exitCode: null,\n          timedOut: false,\n          stdout: '',\n          stderr: '',\n          durationMs: 0,\n          error: error instanceof Error ? error.message : String(error),\n        }\n      }\n    },\n  })\n}\n\n/** The upload tool. */\nexport function sshUploadTool(engine: SshEngine) {\n  return defineTool({\n    name: 'ssh_upload',\n    description: 'Transfer a file FROM this machine (the dsh host) TO a remote SSH host. Use this only when the file must be copied to the remote host. Files that stay on this machine are handled with the local file tools (read / write / edit), not ssh_upload.',\n    parameters: {\n      alias: { type: 'string', required: true, description: 'Host alias from ssh_list.' },\n      localPath: { type: 'string', required: true, description: 'Absolute path of the source file on THIS machine (the dsh host) — not a path on the remote host.' },\n      remotePath: { type: 'string', required: true, description: 'Absolute destination path on the remote SSH host (parent dirs are created).' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean', required: true },\n          transferredBytes: { type: 'integer' },\n          files: { type: 'integer' },\n          error: { type: 'string' },\n        },\n      },\n      render: (_args, value: { ok: boolean; transferredBytes?: number; files?: number; error?: string }) => text(value.ok\n        ? `uploaded ${value.files ?? 1} file(s), ${value.transferredBytes ?? 0} bytes`\n        : `upload failed: ${value.error ?? 'unknown error'}`),\n    },\n    async execute(args) {\n      try {\n        const outcome = await engine.upload(args.alias, args.localPath, args.remotePath, false)\n        return { ok: true, transferredBytes: outcome.bytes, files: outcome.files }\n      } catch (error) {\n        return { ok: false, error: error instanceof Error ? error.message : String(error) }\n      }\n    },\n  })\n}\n\n/** The download tool. */\nexport function sshDownloadTool(engine: SshEngine) {\n  return defineTool({\n    name: 'ssh_download',\n    description: 'Copy a remote FILE from a configured SSH host to this machine (the dsh host). Use this only when the source is on the remote host; files already on this machine are read with the local file tools (read / write / edit), not ssh_download. Directory download is not supported — download files individually.',\n    parameters: {\n      alias: { type: 'string', required: true, description: 'Host alias from ssh_list.' },\n      remotePath: { type: 'string', required: true, description: 'Absolute path of the source file on the remote SSH host.' },\n      localPath: { type: 'string', required: true, description: 'Absolute destination path on THIS machine (the dsh host).' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean', required: true },\n          bytes: { type: 'integer' },\n          error: { type: 'string' },\n        },\n      },\n      render: (_args, value: { ok: boolean; bytes?: number; error?: string }) => text(value.ok\n        ? `downloaded ${value.bytes ?? 0} bytes`\n        : `download failed: ${value.error ?? 'unknown error'}`),\n    },\n    async execute(args) {\n      try {\n        const outcome = await engine.download(args.alias, args.remotePath, args.localPath)\n        return { ok: true, bytes: outcome.bytes }\n      } catch (error) {\n        return { ok: false, error: error instanceof Error ? error.message : String(error) }\n      }\n    },\n  })\n}\n\n/** The tunnel tool. */\nexport function sshTunnelTool(engine: SshEngine) {\n  return defineTool({\n    name: 'ssh_tunnel',\n    description: 'Manage local port-forward tunnels to a configured SSH host. Start a tunnel to reach a remote internal service (database, web UI, API) through 127.0.0.1 on this machine.',\n    parameters: {\n      action: { type: 'string', required: true, enum: ['start', 'list', 'stop', 'stop-all'], description: 'start / list / stop / stop-all.' },\n      alias: { type: 'string', description: 'Host alias (required for start, optional for stop-all).' },\n      remotePort: { type: 'integer', description: 'Port on the remote side (required for start).' },\n      remoteHost: { type: 'string', description: 'Remote host to forward to (default 127.0.0.1 — the server itself).' },\n      localPort: { type: 'integer', description: 'Local listening port (default: auto-assigned).' },\n      tunnelId: { type: 'string', description: 'Tunnel id (required for stop).' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          ok: { type: 'boolean', required: true },\n          tunnel: {\n            type: 'object',\n            additionalProperties: false,\n            properties: {\n              id: { type: 'string', required: true },\n              alias: { type: 'string', required: true },\n              localPort: { type: 'integer', required: true },\n              remoteHost: { type: 'string', required: true },\n              remotePort: { type: 'integer', required: true },\n              state: { type: 'string', enum: ['forwarding', 'connecting', 'failed'], required: true },\n              error: { type: 'string' },\n              startedAt: { type: 'integer', required: true },\n            },\n          },\n          tunnels: {\n            type: 'array',\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                id: { type: 'string', required: true },\n                alias: { type: 'string', required: true },\n                localPort: { type: 'integer', required: true },\n                remoteHost: { type: 'string', required: true },\n                remotePort: { type: 'integer', required: true },\n                state: { type: 'string', enum: ['forwarding', 'connecting', 'failed'], required: true },\n                error: { type: 'string' },\n                startedAt: { type: 'integer', required: true },\n              },\n            },\n          },\n          stopped: { type: 'integer' },\n          error: { type: 'string' },\n        },\n      },\n      render: (_args, value: { ok: boolean; tunnel?: TunnelInfo; tunnels?: TunnelInfo[]; stopped?: number; error?: string }) => {\n        if (value.error !== undefined) return text(`tunnel error: ${value.error}`)\n        if (value.tunnel !== undefined) {\n          if (value.tunnel.state === 'failed') return text(`tunnel failed: ${value.tunnel.error ?? 'unknown error'}`)\n          return text(`tunnel started: ${renderTunnel(value.tunnel)}`)\n        }\n        if (value.tunnels !== undefined) return text(value.tunnels.length === 0 ? 'no active tunnels' : value.tunnels.map(renderTunnel).join('\\n'))\n        return text(`stopped ${value.stopped ?? 0} tunnel(s)`)\n      },\n    },\n    async execute(args) {\n      if (args.action === 'list') {\n        return { ok: true, tunnels: engine.listTunnels() }\n      }\n      if (args.action === 'start') {\n        if (args.alias === undefined || args.remotePort === undefined) {\n          throw new Error('alias and remotePort are required for start')\n        }\n        try {\n          const tunnel = await engine.startTunnel(args.alias, {\n            remotePort: args.remotePort,\n            remoteHost: args.remoteHost,\n            localPort: args.localPort,\n          })\n          return { ok: true, tunnel }\n        } catch (error) {\n          return { ok: false, tunnel: { id: '', alias: args.alias, localPort: 0, remoteHost: args.remoteHost ?? '127.0.0.1', remotePort: args.remotePort, state: 'failed' as const, error: error instanceof Error ? error.message : String(error), startedAt: Date.now() } }\n        }\n      }\n      if (args.action === 'stop') {\n        if (args.tunnelId === undefined) throw new Error('tunnelId is required for stop')\n        const stopped = engine.stopTunnel(args.tunnelId)\n        return stopped\n          ? { ok: true, stopped: 1 }\n          : { ok: false, stopped: 0, error: `tunnel '${args.tunnelId}' not found` }\n      }\n      if (args.action === 'stop-all') {\n        const stopped = engine.stopAllTunnels(args.alias)\n        return { ok: true, stopped }\n      }\n      throw new Error(`unknown action '${String(args.action)}'`)\n    },\n  })\n}\n\n/** The cluster tool. */\nexport function sshClusterTool(engine: SshEngine) {\n  return defineTool({\n    name: 'ssh_cluster',\n    description: 'Run one command concurrently across selected SSH hosts; at least one aliases, environment, or tags filter is required.',\n    parameters: {\n      command: { type: 'string', required: true, description: 'The shell command to run on every matched host.' },\n      aliases: { type: 'array', items: { type: 'string' }, description: 'Optional alias filter; at least one of aliases, environment, or tags is required.' },\n      environment: { type: 'string', description: 'Optional environment filter; at least one selector is required.' },\n      tags: { type: 'array', items: { type: 'string' }, description: 'Optional ALL-tags filter; at least one selector is required.' },\n      timeoutMs: { type: 'integer', description: 'Per-host command execution timeout in milliseconds (default 60000); it does not extend the connection and authentication ceiling (the dsh-ssh connectTimeoutMs setting).' },\n      maxWorkers: { type: 'integer', description: 'Concurrency cap (default 8).' },\n    },\n    output: {\n      schema: {\n        type: 'object',\n        additionalProperties: false,\n        properties: {\n          results: {\n            type: 'array',\n            required: true,\n            items: {\n              type: 'object',\n              additionalProperties: false,\n              properties: {\n                alias: { type: 'string', required: true },\n                ok: { type: 'boolean', required: true },\n                exitCode: { oneOf: [{ type: 'integer' }, { type: 'null' }] },\n                timedOut: { type: 'boolean' },\n                stdout: { type: 'string' },\n                stderr: { type: 'string' },\n                durationMs: { type: 'integer' },\n                error: { type: 'string' },\n              },\n            },\n          },\n        },\n      },\n      render: (_args, value: { results?: ClusterResult[] }) => text(renderCluster(value.results ?? [])),\n    },\n    async execute(args, exec) {\n      const hasSelector = (Array.isArray(args.aliases) && args.aliases.some((alias) => typeof alias === 'string' && alias.trim() !== '')) ||\n        (typeof args.environment === 'string' && args.environment.trim() !== '') ||\n        (Array.isArray(args.tags) && args.tags.some((tag) => typeof tag === 'string' && tag.trim() !== ''))\n      if (!hasSelector) throw new Error('ssh_cluster requires aliases, environment, or tags to limit the target set')\n      // Cancellation reaches every host's in-flight command.\n      return { results: await engine.cluster({ ...args, signal: exec.signal }) }\n    },\n  })\n}\n"
    },
    {
      "path": "packages/dsh-ssh/src/tool-surface.ts",
      "content": "// Generated by scripts/sync-shared.mjs from shared/host/tool-surface.ts. Do not edit this copy; edit the shared source and run \"node scripts/sync-shared.mjs\".\n/**\n * Family-shared tool-surface conventions for the packages that register\n * model-facing tools.\n *\n * One home for the prompt-section placement and the visibility gate this\n * family previously restated per package.\n *\n * Modelled on the official tool packages:\n * - `@deepseek-ai/dsh-tool-subagent` renders its section through\n *   `tools.get(name, context.scope) === undefined ? '' : text`, so guidance\n *   disappears together with a restricted tool.\n * - 21 of the 22 official tool packages register their tools GLOBALLY and gate\n *   them with a setting, not per agent. Only the Agent Teams tool package —\n *   whose tools belong to one membership — installs into each `agent.ctx`.\n *   This family follows the majority: registration stays global so the\n *   registry's per-scope `restrict()` mask (which filters inherited global\n *   tools and REJECTS scope-local names) can still withhold these tools.\n *\n * Structural types only: this copy lands in packages that do not all depend on\n * the same SDK service packages.\n */\n\n/**\n * Prompt-section order for each package's tool guidance.\n *\n * These sit in the family band between the deployment persona and the SDK's\n * `PLAN_POLICY` (500). Values are owned here rather than written per package so\n * the host plugins whose guidance shares one prompt cannot drift into an\n * accidental tie.\n */\nexport const PLUGIN_TOOL_SECTION_ORDERS = {\n  ssh: 150,\n  'task-board': 200,\n  agents: 220,\n} as const\n\n/** One plugin id keyed by {@link PLUGIN_TOOL_SECTION_ORDERS}. */\nexport type PluginToolSectionId = keyof typeof PLUGIN_TOOL_SECTION_ORDERS\n\n/**\n * Order of an external provider extension's own guidance section, right after\n * the band of the plugin it extends.\n *\n * An extension names itself, not the plugin it plugs into, so its order stays\n * out of {@link PLUGIN_TOOL_SECTION_ORDERS}: every package's copy of this module\n * then carries no provider id. The slot still has one owner and cannot collide\n * with a host plugin's band.\n */\nexport const EXTENSION_TOOL_SECTION_ORDER = 210\n\n/**\n * The scoped tool lookup a section provider needs: the registry read for one\n * assembly's scope. Matches `ctx.tools.get(name, scope)`.\n */\nexport interface ScopedToolLookup {\n  get(name: string, scope?: unknown): unknown\n}\n\n/** One assembly context carrying the scope the section is rendered for. */\nexport interface SectionScopeContext {\n  scope?: unknown\n}\n\n/**\n * Build a section provider that renders \\`text\\` only while at least one of\n * \\`toolNames\\` is visible to the rendering scope.\n *\n * The native convention: a tool that a restriction, a preset, or a missing\n * registry removed must not leave guidance behind telling the model to call it.\n * An unreadable registry renders the text unchanged — guidance that outlives a\n * momentary read failure is recoverable; guidance for a tool that is gone is\n * not.\n * @param tools - the scoped tool registry, when the deployment serves one.\n * @param toolNames - registered names the guidance describes.\n * @param text - the guidance rendered while they are reachable.\n * @returns the section text provider.\n */\nexport function visibleToolText(\n  tools: ScopedToolLookup | undefined,\n  toolNames: readonly string[],\n  text: string,\n): (context: SectionScopeContext) => string {\n  if (tools === undefined) return () => text\n  return (context: SectionScopeContext) => {\n    for (const name of toolNames) {\n      try {\n        if (tools.get(name, context.scope) !== undefined) return text\n      } catch {\n        // A refused lookup is not proof the tool is gone; keep the guidance.\n        return text\n      }\n    }\n    return ''\n  }\n}\n"
    },
    {
      "path": "packages/dsh-ssh/src/engine/connection-pool.ts",
      "content": "/**\n * Connection pool: per-alias persistent ssh2 connections with multi-hop jump\n * support, the acquire / dispose / sweep lifecycle, and the pooled exec path.\n */\n\nimport { existsSync, readFileSync } from 'node:fs'\nimport type { Duplex } from 'node:stream'\nimport { Client, type ConnectConfig } from 'ssh2'\nimport type { ExecResult, SshHostEntry } from '../protocol.ts'\nimport { expandHome, normalizeAgentPath, type HostStore } from '../store.ts'\nimport { startProxyCommand, type ProxyTarget } from './proxy-command.ts'\n\n/** Default engine knobs. */\nexport interface EngineOptions {\n  /** Connections idle longer than this are closed (ms). */\n  idleTimeoutMs?: number\n  /**\n   * Ceiling for the whole pre-ready sequence (ms): TCP connect, SSH key\n   * exchange and user authentication. Passed to ssh2's `readyTimeout`.\n   */\n  connectTimeoutMs?: number\n  /** Keepalive ping interval (ms). */\n  keepaliveIntervalMs?: number\n  /** Cap on captured stdout/stderr bytes per exec (ms). */\n  maxOutputBytes?: number\n  /** Default exec timeout (ms). */\n  defaultExecTimeoutMs?: number\n  /** Default cluster concurrency. */\n  defaultMaxWorkers?: number\n  /** SFTP concurrent channel count for transfers. */\n  sftpConcurrency?: number\n}\n\n/**\n * Default ceiling for TCP connect, SSH key exchange and user authentication\n * together (ms). Password authentication behind PAM / LDAP can outlast the\n * previous 15 s ceiling while the server still eventually accepts it.\n */\nexport const DEFAULT_CONNECT_TIMEOUT_MS = 30_000\n\n/** Default engine knobs (applied when an option is omitted). */\nexport const DEFAULTS: Required<EngineOptions> = {\n  idleTimeoutMs: 30 * 60_000,\n  connectTimeoutMs: DEFAULT_CONNECT_TIMEOUT_MS,\n  keepaliveIntervalMs: 15_000,\n  maxOutputBytes: 2 * 1024 * 1024,\n  defaultExecTimeoutMs: 60_000,\n  defaultMaxWorkers: 8,\n  sftpConcurrency: 8,\n}\n\n/** One pooled connection record. */\nexport interface PoolRecord {\n  client: Client\n  /** Jump-chain clients kept alive under the target. */\n  hops: Client[]\n  idleAt: number\n  /** Pinned connections (tunnels) are never swept. */\n  pinned: boolean\n  broken: boolean\n  /** Operations currently running on this connection (sweep guard). */\n  inFlight: number\n}\n\n/**\n * The slice of the engine the pool and exec paths need. The host class\n * (engine.ts facade) satisfies this structurally.\n */\nexport interface PoolEngine {\n  readonly store: HostStore\n  readonly opts: Required<EngineOptions>\n  readonly pool: Map<string, PoolRecord>\n  readonly acquireQueue: Map<string, Promise<PoolRecord>>\n}\n\n/** Build the ssh2 connect config for one entry (key read from disk). */\nexport function buildConnectConfig(entry: SshHostEntry, sock: ConnectConfig['sock'] | undefined, opts: Required<EngineOptions>): ConnectConfig {\n  const config: ConnectConfig = {\n    host: entry.host,\n    port: entry.port,\n    username: entry.user,\n    readyTimeout: opts.connectTimeoutMs,\n    keepaliveInterval: opts.keepaliveIntervalMs,\n    keepaliveCountMax: 3,\n    tryKeyboard: true,\n  }\n  if (sock !== undefined) config.sock = sock\n  if (entry.auth.kind === 'password') {\n    config.password = entry.auth.password\n  } else if (entry.auth.kind === 'agent') {\n    const agentPath = resolveAgentPath(entry.auth.agentPath)\n    if (agentPath === undefined) {\n      throw new Error('ssh-agent is not available: set SSH_AUTH_SOCK or configure an agent path (use \\'pageant\\' for PuTTY Pageant on Windows)')\n    }\n    config.agent = agentPath\n  } else {\n    const keyPath = entry.auth.keyPath === undefined ? undefined : expandHome(entry.auth.keyPath)\n    if (keyPath === undefined || !existsSync(keyPath)) {\n      throw new Error('private key not found: ' + (entry.auth.keyPath ?? '(unset)'))\n    }\n    config.privateKey = readFileSync(keyPath, 'utf8')\n    if (entry.auth.passphrase !== undefined && entry.auth.passphrase !== '') {\n      config.passphrase = entry.auth.passphrase\n    }\n  }\n  // Agent forwarding is additive: it never changes how the host\n  // authenticates, it only lets this connection broker signatures from the\n  // local agent for the remote side (OpenSSH ForwardAgent / ssh -A).\n  if (entry.forwardAgent === true) {\n    // Agent auth already resolved an endpoint, and reusing it keeps the\n    // forwarded agent identical to the one that authenticated.\n    const agentPath = typeof config.agent === 'string'\n      ? config.agent\n      : resolveForwardAgentPath(entry.auth.agentPath)\n    if (agentPath === undefined) {\n      // ssh2's own message for this case (\"You must set a valid agent path to\n      // allow agent forwarding\") names neither the host nor a way out, so the\n      // engine refuses first with an actionable one.\n      throw new Error('agent forwarding is enabled for this host but no ssh-agent endpoint is available: '\n        + 'set SSH_AUTH_SOCK, start Pageant on Windows, or configure an agent path')\n    }\n    config.agent = agentPath\n    config.agentForward = true\n  }\n  return config\n}\n\n/**\n * The default ssh-agent endpoint on Windows: the named pipe the native\n * OpenSSH ssh-agent service listens on. ssh2 connects to a named pipe for any\n * path matching its Windows pipe form, so the default is a real endpoint\n * rather than a protocol name (#1910). PuTTY Pageant is still reachable — it\n * is what the literal `pageant` agent path selects — but it is no longer the\n * assumption.\n */\nexport const WINDOWS_AGENT_PIPE = '\\\\\\\\.\\\\pipe\\\\openssh-ssh-agent'\n\n/** Resolve the ssh2 agent path for 'agent' auth. */\nexport function resolveAgentPath(agentPath?: string): string | undefined {\n  const explicit = normalizeAgentPath(agentPath)\n  if (explicit !== undefined) return explicit\n  const sock = process.env.SSH_AUTH_SOCK\n  if (sock !== undefined && sock !== '') return sock\n  if (process.platform === 'win32') return WINDOWS_AGENT_PIPE\n  return undefined\n}\n\n/*